const rows = $input
  .all()
  .map((item) => item.json)
  .filter((row) => row.secop_portfolio_id);

// Evita consultar dos veces el mismo CO1.BDOS.
const uniquePortfolios = [
  ...new Set(
    rows.map((row) =>
      String(row.secop_portfolio_id).trim()
    )
  ),
];

if (uniquePortfolios.length === 0) {
  return [
    {
      json: {
        has_candidates: false,
        batch_count: 0,
        portfolio_ids: [],
        where_clause: '1 = 0',
      },
    },
  ];
}

// Escapado para la consulta SoQL de Socrata.
const portfolioList = uniquePortfolios
  .map((portfolioId) => {
    const escaped = portfolioId.replace(/'/g, "''");
    return `'${escaped}'`;
  })
  .join(', ');

return [
  {
    json: {
      has_candidates: true,
      batch_count: uniquePortfolios.length,
      portfolio_ids: uniquePortfolios,

      where_clause:
        `proceso IN (${portfolioList})`,

      storage_policy: 'metadata_only',
      binary_download_enabled: false,
    },
  },
];

const candidates = $(
  'Leer procesos pendientes de documentos'
)
  .all(0, $runIndex)
  .map((item) => item.json)
  .filter(
    (row) =>
      row.process_id &&
      row.secop_portfolio_id
  );

// Recupera directamente la respuesta HTTP de esta vuelta.
// No depende de si la entrada viene de Guardar documentos
// o de la rama sin documentos.
const documents = $(
  'Consultar documentos seleccionados WF-003'
)
  .all(0, $runIndex)
  .map((item) => item.json)
  .filter((row) => row.id_documento);

const documentCountByPortfolio = new Map();

for (const document of documents) {
  const portfolioId = String(
    document.proceso ?? ''
  ).trim();

  if (!portfolioId) {
    continue;
  }

  const currentCount =
    documentCountByPortfolio.get(portfolioId) ?? 0;

  documentCountByPortfolio.set(
    portfolioId,
    currentCount + 1
  );
}

const escapeSql = (value) =>
  String(value ?? '').replace(/'/g, "''");

return candidates.map((row) => {
  const portfolioId = String(
    row.secop_portfolio_id ?? ''
  ).trim();

  const documentsFound =
    documentCountByPortfolio.get(portfolioId) ?? 0;

  const openingStatus = String(
    row.opening_status ?? ''
  ).toLowerCase();

  const isOpen =
    openingStatus.includes('abierto');

  return {
    json: {
      process_id:
        String(row.process_id),

      secop_portfolio_id_sql:
        escapeSql(portfolioId),

      secop_process_id_sql:
        escapeSql(row.secop_process_id),

      reference_sql:
        escapeSql(row.reference),

      opening_status_sql:
        escapeSql(row.opening_status),

      process_status_sql:
        escapeSql(row.process_status),

      source_updated_at:
        row.source_updated_at ?? '',

      documents_found:
        documentsFound,

      scan_result:
        documentsFound > 0
          ? 'documents_found'
          : 'no_documents_found',

      next_scan_interval:
        isOpen
          ? '24 hours'
          : '7 days',
    },
  };
});

// Los elementos recibidos son los procesos cuyo resultado
// de escaneo ya fue registrado en PostgreSQL.
const scans = $input
  .all()
  .map((item) => item.json);

// Recupera exclusivamente la respuesta HTTP correspondiente
// a la vuelta actual del ciclo.
const documentItems = $(
  'Consultar documentos seleccionados WF-003'
)
  .all(0, $runIndex)
  .map((item) => item.json);

// Cuando SECOP devuelve [], Always Output Data genera
// un elemento vacío. Solo contamos filas con id_documento.
const documents = documentItems.filter(
  (document) => document.id_documento
);

return [
  {
    json: {
      batch_number: $runIndex + 1,

      batch_process_count:
        scans.length,

      batch_document_count:
        documents.length,

      batch_completed_at:
        new Date().toISOString(),

      storage_policy:
        'metadata_only',

      binary_download_enabled:
        false,
    },
  },
];

const documents = $input
  .all()
  .map((item) => item.json)
  .filter((row) => row.id_documento);

const candidates =
  $('Leer procesos pendientes de documentos')
    .all()
    .map((item) => item.json);

const candidatesByPortfolio =
  new Map(
    candidates
      .filter(
        (row) =>
          row.secop_portfolio_id
          && row.process_id
      )
      .map((row) => [
        String(
          row.secop_portfolio_id
        ).trim(),

        row,
      ])
  );

return documents.map((document) => {
  const portfolioId =
    String(
      document.proceso
      ?? ''
    ).trim();

  const process =
    candidatesByPortfolio.get(
      portfolioId
    )
    ?? {};

  const rawDownloadUrl =
    document.url_descarga_documento;

  const downloadUrl =
    rawDownloadUrl
    && typeof rawDownloadUrl === 'object'
    && !Array.isArray(rawDownloadUrl)
      ? rawDownloadUrl
      : rawDownloadUrl
        ? {
            url:
              String(rawDownloadUrl),
          }
        : {};

  const parsedFileSize =
    Number(
      document.tamanno_archivo
    );

  const normalizedFileSize =
    Number.isSafeInteger(
      parsedFileSize
    )
    && parsedFileSize >= 0
      ? parsedFileSize
      : null;

  const uploadedAt =
    document.fecha_carga
      ? String(
          document.fecha_carga
        )
      : null;

  const normalized = {
    external_document_id:
      String(
        document.id_documento
      ),

    process_id:
      process.process_id
        ? String(
            process.process_id
          )
        : '',

    secop_process_id:
      process.secop_process_id
        ? String(
            process.secop_process_id
          )
        : '',

    secop_portfolio_id:
      portfolioId,

    contract_number:
      document.n_mero_de_contrato
      ?? null,

    file_name:
      document.nombre_archivo
      ?? null,

    file_size_bytes:
      normalizedFileSize,

    file_extension:
      String(
        document.extensi_n
        ?? ''
      )
        .trim()
        .toLowerCase()
        || null,

    description:
      document.descripci_n
      ?? null,

    uploaded_at:
      uploadedAt,

    entity_name:
      document.entidad
      ?? null,

    entity_nit:
      document.nit_entidad
      ?? null,

    download_url:
      downloadUrl,

    download_url_text:
      downloadUrl.url
      ?? null,

    raw_json:
      document,
  };

  return {
    json: {
      ...normalized,

      query_parameters: [
        normalized.external_document_id,
        normalized.process_id,
        normalized.secop_portfolio_id,
        normalized.contract_number,
        normalized.file_name,
        normalized.file_size_bytes,
        normalized.file_extension,
        normalized.description,
        normalized.uploaded_at,
        normalized.entity_name,
        normalized.entity_nit,
        JSON.stringify(
          normalized.download_url
          ?? {}
        ),
        normalized.download_url_text,
        JSON.stringify(
          normalized.raw_json
          ?? {}
        ),
      ],
    },
  };
});
